// === Tab: mySketch ===
class Particle{
	constructor(){
		this.pos = createVector(width/2, height/2)
		this.vel = p5.Vector.random2D()
		this.acc = p5.Vector.random2D().mult(0.1)
	}
	update(){
		this.pos.add(this.vel)
		this.vel.add(this.acc)
		this.vel.mult(0.999)
	}
	draw(){
		push()
			noStroke()
			translate(this.pos.x, this.pos.y)
			ellipse(0, 0, 3, 3)	
		pop()
	}

}

var particles = []
var midPoint

function setup() {
	createCanvas(1112, 834);
	colorMode(HSB, 255);
	background(0);
	for(var i=0; i<3000; i++){
		particles.push(new Particle)
	}
	midPoint = createVector(width/2, height/2)
}

function draw() {
	background(0, 10)

	//get the boundary radius
	var r = pow(frameCount, 0.95)

	//draw the boundary
	push()
		stroke(255, 10)
		noFill()
		ellipse(width/2, height/2, r*2, r*2)	
	pop()

	for(var i=0; i<particles.length; i++){
		particles[i].update()	
		stroke(i/particles.length * 255, 200, 255);
    fill(i/particles.length * 255, 200, 255);		
		particles[i].draw()	

		//give particles reverse speed if it exceed constrain circle area
		var angle = particles[i].pos.copy().sub(midPoint).heading()
		if (particles[i].pos.dist(midPoint)>r + sin(angle/20 + frameCount/30)/2 ){
			//get the dist to circle boundary
			var distToCirBound = particles[i].pos.dist(midPoint)-r
			//get delta vector of particles position and midpoint , then constrain it to modify the force


			var pullVel =	midPoint.copy().sub(particles[i].pos).limit(5).normalize().mult( distToCirBound*3 )
			//apply force
			particles[i].vel.add(pullVel)
		}
	}
}

let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save('pix.jpg');
    lapse = millis();
  }
}

